            .borrow()
            .iter()
            .any(|event| matches!(event, TraceEvent::RunEnd { outcome, .. } if outcome.contains("RegistryPublishUnconfirmed"))),
        "{}",
        trace_lines(&run.context)
    );
    assert_eq!(run.world.elapsed.get(), Duration::from_secs(360));
}

